import { z } from 'zod';

export const idParams = z.object({ id: z.uuid() });
export const variantParams = z.object({ variantId: z.uuid() });

export const cartQuery = z.object({ couponCode: z.string().trim().min(1).max(40).optional() });
export const setQtyBody = z.object({ qty: z.number().int().min(1).max(100_000) });

export const placeOrderBody = z.object({
  addressId: z.uuid(),
  couponCode: z.string().trim().min(1).max(40).optional(),
  /** Generated by the app per checkout attempt; retries with the same key return the same orders. */
  idempotencyKey: z.string().trim().min(8).max(100),
});

export const listOrdersQuery = z.object({
  status: z
    .enum(['placed', 'accepted', 'packed', 'assigned', 'picked_up', 'out_for_delivery', 'delivered', 'cancelled'])
    .optional(),
  retailerId: z.uuid().optional(),
  wholesalerId: z.uuid().optional(),
  limit: z.coerce.number().int().min(1).max(50).default(20),
  cursor: z.string().max(200).optional(),
});

export const reasonBody = z.object({ reason: z.string().trim().min(1).max(500) });
export const optionalReasonBody = z.object({ reason: z.string().trim().min(1).max(500).optional() });
